function diagnose_e2_c2(old,out)
folder=fullfile(old,'E2/cases/V2_C2_3');[D,~,~]=e2r_native(folder);
src=dir(fullfile(folder,'*_authority.mat'));a=load(fullfile(folder,src(1).name));rows={};fields={'sqp_attempted','qp_solved','accepted_steps','rejected_steps','fallback','status','elapsed_s','early_stop_reason','fallback_reason'};
for k=1:numel(a.control_times),z=struct('time_s',a.control_times(k));v=a.diagnostics{k};for j=1:numel(fields),key=fields{j};if isfield(v,key),z.(key)=v.(key);end;end;rows{end+1}=z;end
S=struct2table([rows{:}]);writetable(S,fullfile(out,'tables/C2_solver_diagnostics.csv'));paper_json(fullfile(out,'config/C2_diagnostic_fields.json'),struct('actual_fields',{fieldnames(a.diagnostics{1})},'extracted_fields',{S.Properties.VariableNames}));
segments=[0 8;8 12;12 20;20 24;24 32;32 36;36 46];rows={};
for j=1:7
 lo=segments(j,1);hi=segments(j,2);mask=D.time_s>=lo & D.time_s<hi;if j==7,mask=D.time_s>=lo & D.time_s<=hi;end;T=D(mask,:);sm=S.time_s>=lo & S.time_s<hi;
 v=struct('start_s',lo,'end_s',hi,'native_samples',height(T),'attitude_rmse_deg',sqrt(mean(T.attitude_error_deg.^2)),'pitch_rmse_deg',sqrt(mean(T.pitch_error_deg.^2)),'pitch_peak_error_deg',max(abs(T.pitch_error_deg)),'pitch_q_rate_peak_degps',max(abs(rad2deg(T.q_radps))),'H_start_Nms',T.Hnorm(1),'H_end_Nms',T.Hnorm(end),'Hy_start_Nms',T.Hy(1),'Hy_end_Nms',T.Hy(end),'gimbal_total_travel_rad',sum(sum(abs(diff(T{:,{'g1','g2','g3','g4'}})))),'sigma_min_low',min(T.sigma_min),'pitch_positive_support_low_Nm',min(T.pitch_positive_support_Nm),'pitch_negative_support_low_Nm',min(T.pitch_negative_support_Nm),'cmg_pitch_min_Nm',min(T.cmg_y),'cmg_pitch_max_Nm',max(T.cmg_y),'aero_pitch_min_Nm',min(T.aero_y),'aero_pitch_max_Nm',max(T.aero_y),'gyro_pitch_min_Nm',min(T.gyro_y),'gyro_pitch_max_Nm',max(T.gyro_y),'natural_pitch_min_Nm',min(T.natural_y),'natural_pitch_max_Nm',max(T.natural_y),'cmg_rate_sat_pct',100*mean(T.cmg_rate_sat),'cmg_accel_sat_pct',100*mean(T.cmg_accel_sat),'surface_angle_sat_pct',100*mean(T.surface_angle_sat),'surface_rate_sat_pct',100*mean(T.surface_rate_sat),'aero_command_error_rms_Nm',sqrt(mean((T.aero_cmd_y-T.aero_y).^2)),'qbar_min_Pa',min(T.qbar_Pa),'qbar_max_Pa',max(T.qbar_Pa),'height_min_m',min(T.height_m),'height_max_m',max(T.height_m),'speed_min_mps',min(T.speed_mps),'speed_max_mps',max(T.speed_mps),'alpha_min_deg',min(T.alpha_deg),'alpha_max_deg',max(T.alpha_deg));
 for key={'sqp_attempted','qp_solved','accepted_steps','rejected_steps','fallback'},name=key{1};if ismember(name,S.Properties.VariableNames),v.(['solver_' name '_sum'])=sum(S.(name)(sm));end;end
 v.solver_ticks=sum(sm);rows{end+1}=v;
end
T=struct2table([rows{:}]);writetable(T,fullfile(out,'tables/C2_segment_metrics.csv'));
samples=[7.8 8 12 19.8 20 24 31.8 32 36 46];[~,ix]=min(abs(D.time_s-samples),[],1);writetable(D(ix,:),fullfile(out,'tables/C2_event_boundary_states.csv'));
events={};for j=1:3,onset=[8 20 32];on=onset(j);during=D.time_s>=on & D.time_s<=on+4;stop=min(on+14,60);if j<3,stop=onset(j+1);end;post=D.time_s>on+4 & D.time_s<=stop;[~,k]=min(abs(D.time_s-(on-.2)));v=struct('event_index',j,'onset_s',on,'post_end_s',stop,'post_duration_s',stop-on-4,'maneuver_rmse_deg',sqrt(mean(D.attitude_error_deg(during).^2)),'post_rmse_deg',sqrt(mean(D.attitude_error_deg(post).^2)),'pre_H_Nms',D.Hnorm(k),'pre_Hy_Nms',D.Hy(k),'pre_sigma_min',D.sigma_min(k),'pre_positive_support_Nm',D.pitch_positive_support_Nm(k),'pre_negative_support_Nm',D.pitch_negative_support_Nm(k));events{end+1}=v;end
E=struct2table([events{:}]);writetable(E,fullfile(out,'tables/C2_3maneuvers_recomputed.csv'));
% Keep full native evidence locally; display plots alone are downsampled.
writetable(D,fullfile(out,'tables/C2_native_diagnostic.csv'));
f=figure('Visible','off');tiledlayout(4,1);nexttile;plot(D.time_s,D.pitch_deg,D.time_s,D.ref_pitch_deg,'--');ylabel('Pitch (deg)');legend('actual','reference');nexttile;plot(D.time_s,D.pitch_error_deg);ylabel('Pitch error (deg)');nexttile;plot(D.time_s,[D.aero_y D.cmg_y D.pitch_control_total_Nm]);ylabel('Moment (N m)');legend('actual aero incl natural','actual CMG','aero+CMG');nexttile;plot(D.time_s,[D.natural_y D.disturbance_y D.gyro_y D.rigid_y D.net_y]);ylabel('Dynamics (N m)');legend('natural aero','disturbance','-omega x H','-omega x Jomega','net Jomegadot');decorate;v3_savefig(f,out,'C2_pitch_error_and_torque');
f=figure('Visible','off');tiledlayout(4,1);nexttile;plot(D.time_s,rad2deg(D{:,{'g1','g2','g3','g4'}}));ylabel('Gimbal (deg)');nexttile;plot(D.time_s,D{:,{'Hx','Hy','Hz','Hnorm'}});ylabel('H (N m s)');legend('Hx','Hy','Hz','norm');nexttile;plot(D.time_s,[D.pitch_positive_support_Nm D.pitch_negative_support_Nm]);ylabel('Pitch support (N m)');legend('positive projection','negative projection');nexttile;plot(D.time_s,D.sigma_min);ylabel('sigma min A');decorate;nexttile(1);legend({'g1','g2','g3','g4'},'AutoUpdate','off');nexttile(2);legend({'Hx','Hy','Hz','norm'},'AutoUpdate','off');nexttile(3);legend({'positive projection','negative projection'},'AutoUpdate','off');label_c2_figure('state');v3_savefig(f,out,'C2_CMG_state_and_authority');
f=figure('Visible','off');tiledlayout(4,1);nexttile;plot(D.time_s,rad2deg(D{:,{'nu1','nu2','nu3','nu4'}}));ylabel('Gimbal rate (deg/s)');nexttile;plot(D.time_s,[D.cmg_rate_sat D.cmg_accel_sat D.surface_angle_sat D.surface_rate_sat]);ylabel('Actual limit flags');legend('CMG rate','CMG acceleration','surface angle','surface rate');nexttile;stairs(S.time_s,[S.sqp_attempted S.qp_solved S.accepted_steps S.rejected_steps]);ylabel('Solver counts');legend('SQP tried','QP solved','accepted','rejected');nexttile;plot(D.time_s,D.pitch_error_deg);hold on;stairs(S.time_s,S.fallback);ylabel('Error / fallback');legend('pitch error deg','fallback');decorate;nexttile(1);legend({'nu1','nu2','nu3','nu4'},'AutoUpdate','off');nexttile(2);legend({'CMG rate','CMG acceleration','surface angle','surface rate'},'AutoUpdate','off');nexttile(3);legend({'SQP tried','QP solved','accepted','rejected'},'AutoUpdate','off');nexttile(4);legend({'pitch error deg','fallback'},'AutoUpdate','off');label_c2_figure('actuator');v3_savefig(f,out,'C2_actuator_and_solver');
paper_json(fullfile(out,'reports/C2_readonly_acceptance.json'),struct('source_raw',fullfile(folder,'sim_output.mat'),'source_sha256',paper_hash(fullfile(folder,'sim_output.mat')),'new_simulations',0,'native_samples',height(D),'native_period_s',.001,'segments',7,'event_metrics_recomputed',true));
fprintf('C2_DIAG_COMPLETE native=%d no simulation\n',height(D));
end
function decorate
axeslist=findall(gcf,'Type','axes');for k=1:numel(axeslist),axes(axeslist(k));xlim([0 46]);grid on;for on=[8 20 32],xline(on,'k:','HandleVisibility','off');xline(on+4,'k--','HandleVisibility','off');end;end;xlabel('Physical time (s)');
end
